	-- No longer in the guide (its English changed or it went away): reuse or delete.
	-- ["Any {skill:182} trainer of your faction teaches Apprentice {skill:182} (character level 5); the arrow picks the nearest."] = "Любой учитель вашей фракции ({skill:182}) обучает навыку {skill:182}, ранг «Ученик» (уровень персонажа 5); стрелка ведет к ближайшему.",
	-- ["Journeyman {skill:182} raises the cap to 150; it needs skill 50 and character level 10. The arrow picks the nearest {skill:182} trainer of your faction."] = "{skill:182}, ранг «Подмастерье»: предел 150; нужен навык 50 и уровень персонажа 10. Стрелка ведет к ближайшему учителю вашей фракции ({skill:182}).",
	-- ["Pick every {item:2447} (1, green), {item:765} (1, green), {item:2449} (15, green), {item:785} (50, green), {item:2450} (70, yellow), {item:3820} (85, orange), {item:2453} (100, orange), {object:1623} (from 115) you pass and circle the waypoints until {skill:182} 125. Zone level 20-30."] = "Собирайте по пути: {item:2447} (1, зеленый), {item:765} (1, зеленый), {item:2449} (15, зеленый), {item:785} (50, зеленый), {item:2450} (70, желтый), {item:3820} (85, оранжевый), {item:2453} (100, оранжевый), {object:1623} (с 115) – и обходите точки маршрута, пока {skill:182} не достигнет 125. Уровень зоны: 20-30.",
	-- ["Pick every {item:2447} (1, orange), {item:765} (1, orange), {item:2449} (from 15) you pass and circle the waypoints until {skill:182} 50. Zone level 1-15. Expect about 60 herbs for these 49 points."] = "Собирайте по пути: {item:2447} (1, оранжевый), {item:765} (1, оранжевый), {item:2449} (с 15) – и обходите точки маршрута, пока {skill:182} не достигнет 50. Уровень зоны: 1-15. На эти 49 очков уйдет около 60 трав.",
	-- ["Pick every {item:2447} (1, orange), {item:765} (1, orange), {object:656161} (1, orange), {object:656160} (1, orange), {item:2449} (from 15) you pass and circle the waypoints until {skill:182} 50. Zone level 1-10. Expect about 60 herbs for these 49 points."] = "Собирайте {item:2447} (1, оранжевый), {item:765} (1, оранжевый), {object:656161} (1, оранжевый), {object:656160} (1, оранжевый), {item:2449} (from 15) по пути и обойдите точки до навыка {skill:182} 50. Уровень зоны 1-10. На эти 49 очков нужно около 60 трав.",
	-- ["Pick every {item:2447} (1, orange), {item:765} (1, orange), {object:656161} (1, orange, rare), {object:656160} (1, orange), {item:2449} (from 15) you pass and circle the waypoints until {skill:182} 50. Zone level 1-10. Expect about 60 herbs for these 49 points."] = "Собирайте {item:2447} (1, оранжевый), {item:765} (1, оранжевый), {object:656161} (1, оранжевый, редкий), {object:656160} (1, оранжевый), {item:2449} (from 15) по пути и обойдите точки до навыка {skill:182} 50. Уровень зоны 1-10. На эти 49 очков нужно около 60 трав.",
	-- ["Pick every {item:2447} (1, orange), {item:765} (1, orange), {object:656161} (1, orange, rare), {object:656160} (1, orange, rare), {item:2449} (from 15) you pass and circle the waypoints until {skill:182} 50. Zone level 1-10. Expect about 60 herbs for these 49 points."] = "Собирайте по пути: {item:2447} (1, оранжевый), {item:765} (1, оранжевый), {object:656161} (1, оранжевый, редкий), {object:656160} (1, оранжевый, редкий), {item:2449} (с 15) – и обходите точки маршрута, пока {skill:182} не достигнет 50. Уровень зоны: 1-10. Рассчитывайте примерно на 60 трав для этих 49 очков.",
	-- ["Pick every {item:2447} (1, yellow), {item:765} (1, yellow), {item:2449} (15, yellow), {item:785} (50, orange), {item:2450} (from 70) you pass and circle the waypoints until {skill:182} 100. {item:785} and {item:2450} sometimes give a {item:2452} as well. Zone level 10-20. Expect about 140 herbs for these 50 points."] = "Собирайте по пути: {item:2447} (1, желтый), {item:765} (1, желтый), {item:2449} (15, желтый), {item:785} (50, оранжевый), {item:2450} (с 70) – и обходите точки маршрута, пока {skill:182} не достигнет 100. Иногда {item:785} и {item:2450} дают еще и {item:2452}. Уровень зоны: 10-20. На эти 50 очков уйдет около 140 трав.",
